        content: [{ type: 'text' as const, text }],
        ...(resultMeta ? { _meta: resultMeta } : {}),
        ...(softError ? { isError: true } : {}),
      };
    } catch (error: any) {
      const tool = getTool(name);
      const requiredAccess = tool
        ? getRequiredAccessLevel(name, args ?? {}, isAuthorizationReadOnly(tool))
