366				}
367			};
368		}, []);
369	
370		const setViewState = useCallback(
371			(key: string, value: ViewStateValue) => {
372				if (!key || key.length > 120) return;
373				const next = { ...viewStateRef.current, [key]: value };
374				viewStateRef.current = next;
375				setViewStateValue(next);
376				if (!app || toolCallId.current === null || toolCallName.current === null)
377					return;
378				if (saveStateTimer.current !== null) {
379					window.clearTimeout(saveStateTimer.current);
380				}
381				saveStateTimer.current = window.setTimeout(() => {
382					saveStateTimer.current = null;
383					const capability = snapshotCapability.current;
384					void app
385						.callServerTool({
386							name: "save_lobu_app_state",
387							arguments: {
388								tool_call_id: toolCallId.current,
389								tool_name: toolCallName.current,
390								view_state: viewStateRef.current,
391								...(capability
392									? { snapshot_capability: capability }
393									: {}),
394							},
395							...(capability
396								? {
397										_meta: {
398											"lobu/mcp-app-snapshot-capability": capability,
399										},
400									}
401								: {}),
402						})
403						.then((result) => {
404							if (
405								capability &&
406								result.isError !== true &&
407								isStructuredObject(result.structuredContent) &&
408								result.structuredContent.saved === true &&
409								snapshotCapability.current === capability
410							) {
411								snapshotCapability.current = null;
412							}
413						})
414						.catch(() => {
415							console.warn("[mcp-app] failed to save view state");
416						});
417				}, 250);
418			},
419			[app],
420		);
421	
422		const callTool = async (name: string, args: ToolArgs) => {
423			if (!app) {
424				if (!isEmbedded) {
425					console.log("[mcp-app] tools/call", name, args);
426					setLastResult((last) => ({
427						isError: false,
428						seq: (last?.seq ?? 0) + 1,
429					}));
430				}
431				return;
432			}
433			try {
434				const result = await app.callServerTool({
435					name,
436					arguments: args,
437					...(name === "resolve_lobu_approval" && approvalCapability
438						? { _meta: { "lobu/approval-capability": approvalCapability } }
439						: {}),
440				});
441				if (isStructuredObject(result.structuredContent)) {
442					const nextData = result.structuredContent as T;
443					hasLiveToolOutput.current = true;
444					hasData.current = true;
445					setData(nextData);
446					persistOpenAiData(openAiCompatTargets(), nextData);
447				}
448				if (name === "resolve_lobu_approval" && result.isError !== true) {
449					setApprovalCapability(null);
450				}
451				setLastResult((last) => ({
452					isError: result.isError === true,
453					seq: (last?.seq ?? 0) + 1,
454				}));
455			} catch {
456				setLastResult((last) => ({
457					isError: true,
458					seq: (last?.seq ?? 0) + 1,
459				}));
460			}
461		};
462	
463		const openLink = async (href: string) => {
464			if (!isExternalHttpUrl(href)) {
465				console.warn("[mcp-app] refused non-HTTP external link");
466				return;
467			}
468			if (!app) {
469				if (!isEmbedded) console.log("[mcp-app] ui/open-link", href);
470				return;
471			}
472			try {
473				const result = await app.openLink({ url: href });
474				if (result.isError) console.warn("[mcp-app] host rejected external link");
475			} catch {
476				console.warn("[mcp-app] host rejected external link");
477			}
478		};
479	
480		return (
481			<McpAppContext.Provider
482				value={{
483					data,
484					toolName,
485					viewState,
486					setViewState,
487					callTool,
488					openLink,
489					lastResult,
490					allowSpaHostedViews,
491				}}
492			>
493				{children}
494			</McpAppContext.Provider>
495		);
496	}
