      }
    }
  ],
  "overall_correctness": "patch is incorrect",
  "overall_explanation": "The new restoration state machine has two reproducible ordering bugs: a fresh capability can be resolved against a stale host identity, and delayed widget-state echoes can resurrect explicitly unavailable results. Both can display the wrong historical card despite the expanded test coverage.",
  "overall_confidence_score": 0.99
}

